from .prisma_data_transfer import (PrismaUDGUpLinkDataTransfer,
                                   PrismaUDGDownLinkDataTransfer,
                                   PrismaUDGUpDownLinkDataTransfer,
                                   PrismaIperfUpLinkDataTransfer,
                                   PrismaIperfDownLinkDataTransfer,
                                   PrismaIperfUpDownLinkDataTransfer)


class DataTransferFactory(object):
    def __init__(self, **kwargs):
        pass

    def create(self, **kwargs):
        pass


class UDGUpLinkDataTransferFactory(DataTransferFactory):
    def __init__(self, **kwargs):
        super(UDGUpLinkDataTransferFactory, self).__init__(**kwargs)

    def create(self, alias, dt_definition, configuration, prisma, throughput_checker, **kwargs):
        dt = PrismaUDGUpLinkDataTransfer(alias=alias,
                                         dt_definition=dt_definition,
                                         configuration=configuration,
                                         checkthroughput=throughput_checker,
                                         prisma=prisma)
        return dt


